			КонецЦикла;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

// Добавляет в дерево подзадачи задачи с их действиями.
//
// Параметры:
//  Строки - Массив - накопительный список строк текста, дополняется.
//  Задача - ДокументСсылка.Задача - задача.
//
Процедура ДобавитьДеревоПодзадач(Строки, Задача)

	Для Каждого Подзадача Из ДочерниеЗадачи(Задача) Цикл

		РеквизитыПодзадачи = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(
			Подзадача, "Заголовок, Автор, ДатаСоздания");

		СтрокаПодзадачи = "    " + СокрЛП(Строка(РеквизитыПодзадачи.Заголовок));
		ПредставлениеАвтора = ПредставлениеУчастника(РеквизитыПодзадачи.Автор);
		Если ЗначениеЗаполнено(ПредставлениеАвтора) Тогда
			СтрокаПодзадачи = СтрокаПодзадачи + " - автор: " + ПредставлениеАвтора;
		КонецЕсли;
		Строки.Добавить(СтрокаПодзадачи);

		ДобавитьДействияПодзадачи(Строки, Подзадача);

	КонецЦикла;

КонецПроцедуры

// Добавляет в дерево действия подзадачи с комментариями.
//
// Параметры:
//  Строки - Массив - накопительный список строк текста, дополняется.
//  Подзадача - ДокументСсылка.Задача - подзадача.
//
Процедура ДобавитьДействияПодзадачи(Строки, Подзадача)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ
		|	ДействиеЗадачи.ДатаНачала КАК ДатаНачала,
		|	ДействиеЗадачи.ДатаВыполнения КАК ДатаВыполнения,
		|	ДействиеЗадачи.ОсобыйАвтор КАК ОсобыйАвтор,
		|	ДействиеЗадачи.Исполнитель КАК Исполнитель,
		|	ДействиеЗадачи.ФактическийИсполнитель КАК ФактическийИсполнитель,
		|	ДействиеЗадачи.СостояниеУчастникаЗадачи КАК СостояниеУчастникаЗадачи,
		|	ДействиеЗадачи.РезультатДействия КАК РезультатДействия,
		|	ДействиеЗадачи.РезультатДействияТекстом КАК РезультатДействияТекстом
		|ИЗ
		|	Документ.ДействиеЗадачи КАК ДействиеЗадачи
		|ГДЕ
		|	ДействиеЗадачи.Задача = &Задача
		|УПОРЯДОЧИТЬ ПО
		|	ДатаНачала ВОЗР,
		|	ДатаВыполнения ВОЗР";
	Запрос.УстановитьПараметр("Задача", Подзадача);

	РеквизитыПодзадачи = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(Подзадача, "Автор");

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл

		Автор = ?(ЗначениеЗаполнено(Выборка.ОсобыйАвтор), Выборка.ОсобыйАвтор, РеквизитыПодзадачи.Автор);
		Адресат = ?(ЗначениеЗаполнено(Выборка.ФактическийИсполнитель),
			Выборка.ФактическийИсполнитель, Выборка.Исполнитель);
		Дата = ?(ЗначениеЗаполнено(Выборка.ДатаВыполнения), Выборка.ДатаВыполнения, Выборка.ДатаНачала);

		СтрокаДействия = "        " + ЗаголовокЭтапа(
			Дата, Автор, Адресат, СокрЛП(Строка(Выборка.СостояниеУчастникаЗадачи)));

		Строки.Добавить(СтрокаДействия);

		ТекстРезультата = ТекстРезультатаДействия(Выборка);
		Если ЗначениеЗаполнено(ТекстРезультата) Тогда
			Для Каждого СтрокаРезультата Из ТекстПоШиринеПострочно(ТекстРезультата) Цикл
				Строки.Добавить("            " + СтрокаРезультата);
			КонецЦикла;
		КонецЕсли;

	КонецЦикла;

КонецПроцедуры

// Возвращает таблицу "Все процессы и задачи": процесс, задачи-исполнители, подзадачи
// и их действия с исполнителями, сроками, датами выполнения и комментариями.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  ТаблицаЗначений - таблица процессов и задач:
//   * Уровень - Число - уровень вложенности;
//   * ПроцессЗадача - Строка - процесс или задача;
//   * Исполнитель - Строка - исполнитель;
//   * Срок - Строка - срок исполнения;
//   * ДатаВыполнения - Строка - дата выполнения;
//   * Комментарий - Строка - комментарий.
//
Функция ТаблицаПроцессовИЗадач(Задача) Экспорт

	Таблица = Новый ТаблицаЗначений;
	Таблица.Колонки.Добавить("Уровень", Новый ОписаниеТипов("Число"));
	Таблица.Колонки.Добавить("ПроцессЗадача", Новый ОписаниеТипов("Строка"));
	Таблица.Колонки.Добавить("Исполнитель", Новый ОписаниеТипов("Строка"));
	Таблица.Колонки.Добавить("Срок", Новый ОписаниеТипов("Строка"));
	Таблица.Колонки.Добавить("ДатаВыполнения", Новый ОписаниеТипов("Строка"));
	Таблица.Колонки.Добавить("Комментарий", Новый ОписаниеТипов("Строка"));
	Таблица.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
	Таблица.Колонки.Добавить("ЭтоЗадача", Новый ОписаниеТипов("Булево"));

	Если Не ЗначениеЗаполнено(Задача) Тогда
		Возврат Таблица;
	КонецЕсли;

	// Процесс.
	СтрокаПроцесса = Таблица.Добавить();
	СтрокаПроцесса.Уровень = 0;
	СтрокаПроцесса.ПроцессЗадача = СокрЛП(Строка(Задача.Заголовок));

	ДатыВыполненияПоАвторам = ДатыВыполненияПоАвторам(Задача);

	БизнесПроцесс = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Задача, "Источник");
	Если ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Исполнение") Тогда
		ДобавитьЗадачиИсполнителиВТаблицу(Таблица, БизнесПроцесс, ДатыВыполненияПоАвторам);
	КонецЕсли;

	// Все задачи по предмету (приложению), как в типовой форме "Все процессы и задачи":
	// задачи пунктов протокола, ознакомления, вопросы и повторные циклы, с иерархией.
	Предмет = ПредметЗадачи(Задача);
	Если ЗначениеЗаполнено(Предмет) Тогда
		ЗадачиДерева = РаботаСЗадачами.ЗадачиПоПриложению(Предмет, Истина);
	Иначе
		ЗадачиДерева = Новый Массив;
	КонецЕсли;

	// Все задачи ветки: подзадачи, вопросы и ознакомления по действиям задач.
	СобратьПотомковЗадач(ЗадачиДерева);

	Если ЗадачиДерева.Количество() = 0 Тогда
		ДобавитьПодзадачиВТаблицу(Таблица, Задача);
	Иначе
		ЗадачиИерархии = УпорядочитьЗадачиПоИерархии(ЗадачиДерева);
		Для Каждого ЭлементИерархии Из ЗадачиИерархии Цикл
			ДобавитьСтрокуЗадачиВТаблицу(Таблица, ЭлементИерархии.Задача, ЭлементИерархии.Уровень);
		КонецЦикла;
	КонецЕсли;

	// Задачи-исполнители всех процессов по предмету: ознакомления, вопросы, повторные циклы.
	Если ЗначениеЗаполнено(Предмет) Тогда

		УровниЗадач = Новый Соответствие;
		Если ЗадачиДерева.Количество() > 0 Тогда
			Для Каждого ЭлементИерархии Из ЗадачиИерархии Цикл
				УровниЗадач[ЭлементИерархии.Задача] = ЭлементИерархии.Уровень;
			КонецЦикла;
		КонецЕсли;

		ЗадачиИсполнители = Новый Массив;
		ДобавитьЗадачиИсполнителиПоПредмету(ЗадачиИсполнители, Предмет);

		// Процессы, у которых предмет - сама задача: ознакомление с задачей, вопросы по ней.
		Если ЗадачиДерева.Количество() > 0 И ЗадачиДерева.Количество() <= 100 Тогда
			Для Каждого ЗадачаВетки Из ЗадачиДерева Цикл
				ДобавитьЗадачиИсполнителиПоПредмету(ЗадачиИсполнители, ЗадачаВетки);
			КонецЦикла;
		КонецЕсли;

		// Процессы, у которых предмет - задача-исполнитель: ознакомления с исполнением, вопросы.
		Если ЗадачиИсполнители.Количество() > 0 И ЗадачиИсполнители.Количество() <= 60 Тогда
			ЗадачиПервогоУровня = Новый Массив;
			Для Каждого ЗадачаИсполнитель Из ЗадачиИсполнители Цикл
				ЗадачиПервогоУровня.Добавить(ЗадачаИсполнитель);
			КонецЦикла;
			Для Каждого ЗадачаИсполнитель Из ЗадачиПервогоУровня Цикл
				ДобавитьЗадачиИсполнителиПоПредмету(ЗадачиИсполнители, ЗадачаИсполнитель);
			КонецЦикла;
		КонецЕсли;

		Родители = РодителиЗадачИсполнителей(ЗадачиИсполнители);

		Для Каждого ЗадачаИсполнитель Из ЗадачиИсполнители Цикл

			Родитель = Родители[ЗадачаИсполнитель];
			Уровень = 1;
			Если Родитель <> Неопределено И УровниЗадач[Родитель] <> Неопределено Тогда
				Уровень = УровниЗадач[Родитель] + 1;
			КонецЕсли;

			СтрокаИсполнителя = Таблица.Добавить();
			СтрокаИсполнителя.Уровень = Уровень;
			СтрокаИсполнителя.ЭтоЗадача = Истина;
			СтрокаИсполнителя.ПроцессЗадача = СокрЛП(Строка(ЗадачаИсполнитель));
			СтрокаИсполнителя.Исполнитель = СокрЛП(Строка(ЗадачаИсполнитель.Исполнитель));

			Если Родитель <> Неопределено Тогда
				СтрокаИсполнителя.Комментарий = НСтр("ru = 'От: '")
					+ СокрЛП(Строка(Родитель));
			КонецЕсли;

		КонецЦикла;

	КонецЕсли;

	// Вложенность показываем отступами в названии процесса или задачи.
	Для Каждого Строка Из Таблица Цикл
		Отступ = "";
		НомерУровня = 1;
		Пока НомерУровня < Строка.Уровень Цикл
			Отступ = Отступ + Символ(160) + Символ(160) + Символ(160) + Символ(160);
			НомерУровня = НомерУровня + 1;
		КонецЦикла;
		Строка.ПроцессЗадача = Отступ + Строка.ПроцессЗадача;
	КонецЦикла;

	Возврат Таблица;

КонецФункции

// Возвращает предмет (приложение) задачи: протокол, документ или иной объект.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Произвольный - предмет задачи или Неопределено.
//
Функция ПредметЗадачи(Задача)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	ЗадачаПриложения.Приложение КАК Приложение
		|ИЗ
		|	Документ.Задача.Приложения КАК ЗадачаПриложения
		|ГДЕ
		|	ЗадачаПриложения.Ссылка = &Задача";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() И ЗначениеЗаполнено(Выборка.Приложение) Тогда
		Возврат Выборка.Приложение;
	КонецЕсли;

	БизнесПроцесс = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Задача, "Источник");
	Если ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Исполнение") Тогда
		ЗапросПредметов = Новый Запрос;
		ЗапросПредметов.Текст =
			"ВЫБРАТЬ ПЕРВЫЕ 1
			|	Предметы.Предмет КАК Предмет
			|ИЗ
			|	БизнесПроцесс.Исполнение.Предметы КАК Предметы
			|ГДЕ
			|	Предметы.Ссылка = &БизнесПроцесс";
		ЗапросПредметов.УстановитьПараметр("БизнесПроцесс", БизнесПроцесс);

		ВыборкаПредметов = ЗапросПредметов.Выполнить().Выбрать();
		Если ВыборкаПредметов.Следующий() Тогда
			Возврат ВыборкаПредметов.Предмет;
		КонецЕсли;
	КонецЕсли;

	Возврат Неопределено;

КонецФункции

// Упорядочивает задачи по иерархии: родительские задачи раньше подчиненных.
//
// Параметры:
//  Задачи - Массив - задачи.
//
// Возвращаемое значение:
//  Массив из Структура:
//   * Задача - ДокументСсылка.Задача - задача;
//   * Уровень - Число - уровень вложенности.
//
Функция УпорядочитьЗадачиПоИерархии(Задачи)

	СписокЗадач = Новый Массив;
	Для Каждого Задача Из Задачи Цикл
		Если СписокЗадач.Найти(Задача) = Неопределено Тогда
			СписокЗадач.Добавить(Задача);
		КонецЕсли;
	КонецЦикла;

	РеквизитыЗадач = ОбщегоНазначения.ЗначенияРеквизитовОбъектов(СписокЗадач,
		"ВышестоящаяЗадача, ДатаСоздания");

	Дети = Новый Соответствие;
	Родители = Новый Соответствие;

	Для Каждого Задача Из СписокЗадач Цикл
		Реквизиты = РеквизитыЗадач[Задача];
		Родитель = Реквизиты.ВышестоящаяЗадача;
		Если ЗначениеЗаполнено(Родитель) И СписокЗадач.Найти(Родитель) <> Неопределено Тогда
			СписокДетей = Дети[Родитель];
			Если СписокДетей = Неопределено Тогда
				СписокДетей = Новый Массив;
				Дети[Родитель] = СписокДетей;
			КонецЕсли;
			СписокДетей.Добавить(Задача);
			Родители[Задача] = Родитель;
		КонецЕсли;
	КонецЦикла;

	Результат = Новый Массив;

	Для Каждого Задача Из СписокЗадач Цикл
		Если Родители[Задача] = Неопределено Тогда
			ДобавитьЗадачуСДетьми(Задача, 1, Дети, Результат);
		КонецЕсли;
	КонецЦикла;

	Возврат Результат;

КонецФункции

// Добавляет задачу и ее подзадачи в список с уровнями вложенности.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//  Уровень - Число - уровень вложенности.
//  Дети - Соответствие - подзадачи по родителям.
//  Результат - Массив - накопительный список, дополняется.
//
Процедура ДобавитьЗадачуСДетьми(Задача, Уровень, Дети, Результат)

	Элемент = Новый Структура("Задача, Уровень", Задача, Уровень);
	Результат.Добавить(Элемент);

	СписокДетей = Дети[Задача];
	Если СписокДетей <> Неопределено Тогда
		Для Каждого Ребенок Из СписокДетей Цикл
			ДобавитьЗадачуСДетьми(Ребенок, Уровень + 1, Дети, Результат);
		КонецЦикла;
	КонецЕсли;

КонецПроцедуры

// Добавляет в таблицу строку задачи и ее действия.
//
// Параметры:
//  Таблица - ТаблицаЗначений - таблица процессов и задач, дополняется.
//  Задача - ДокументСсылка.Задача - задача.
//  Уровень - Число - уровень вложенности.
//
Процедура ДобавитьСтрокуЗадачиВТаблицу(Таблица, Задача, Уровень)

	РеквизитыЗадачи = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(
		Задача, "Заголовок, Автор, Срок, ДатаВыполнения, ДатаСоздания, Описание");

	Строка = Таблица.Добавить();
	Строка.Уровень = Уровень;
	Строка.ЭтоЗадача = Истина;
	Строка.ПроцессЗадача = СокрЛП(Строка(РеквизитыЗадачи.Заголовок));
	Строка.Исполнитель = ИсполнительЗадачи(Задача, РеквизитыЗадачи.Автор);

	Если ЗначениеЗаполнено(РеквизитыЗадачи.Срок) Тогда
		Строка.Срок = Формат(РеквизитыЗадачи.Срок, "ДФ='dd.MM.yyyy HH:mm'");
	КонецЕсли;
	Если ЗначениеЗаполнено(РеквизитыЗадачи.ДатаВыполнения) Тогда
		Строка.ДатаВыполнения = Формат(РеквизитыЗадачи.ДатаВыполнения, "ДФ='dd.MM.yyyy HH:mm'");
	КонецЕсли;

	Строка.Дата = ?(ЗначениеЗаполнено(РеквизитыЗадачи.ДатаВыполнения),
		РеквизитыЗадачи.ДатаВыполнения, РеквизитыЗадачи.ДатаСоздания);

	Строка.Комментарий = СокрЛП(Строка(РеквизитыЗадачи.Описание));

	ДобавитьДействияВТаблицу(Таблица, Задача, РеквизитыЗадачи.Автор, Уровень + 1);

КонецПроцедуры

// Возвращает исполнителя задачи: участника с видом "Исполнитель" или автора.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//  Автор - ОпределяемыйТип.УчастникЗадач - автор задачи.
//
// Возвращаемое значение:
//  Строка - представление исполнителя.
//
Функция ИсполнительЗадачи(Задача, Автор)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	Участники.Участник КАК Участник
		|ИЗ
		|	Документ.Задача.Участники КАК Участники
		|		ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.ВидыУчастниковЗадач КАК ВидыУчастниковЗадач
		|		ПО Участники.ВидУчастника = ВидыУчастниковЗадач.Ссылка
		|ГДЕ
		|	Участники.Ссылка = &Задача
		|	И ВидыУчастниковЗадач.ЭтоИсполнитель = ИСТИНА";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() Тогда
		Возврат ПредставлениеУчастника(Выборка.Участник);
	КонецЕсли;

	Возврат ПредставлениеУчастника(Автор);

КонецФункции

// Возвращает даты выполнения действий по авторам из журнала истории задач.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Соответствие - автор (участник) и дата его действия.
//
Функция ДатыВыполненияПоАвторам(Задача)

	ДатыПоАвторам = Новый Соответствие;

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ
		|	ИсторияЗадач.Дата КАК Дата,
		|	ИсторияЗадач.Автор КАК Автор,
		|	ИсторияЗадач.Событие КАК Событие
		|ИЗ
		|	РегистрСведений.ИсторияЗадач КАК ИсторияЗадач
		|ГДЕ
		|	ИсторияЗадач.Задача = &Задача
		|УПОРЯДОЧИТЬ ПО
		|	Дата ВОЗР";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл

		НазваниеСобытия = СокрЛП(Строка(Выборка.Событие));
		Если Найти(НазваниеСобытия, "ыполн") = 0
			И Найти(НазваниеСобытия, "знаком") = 0 Тогда
			Продолжить;
		КонецЕсли;

		Если ЗначениеЗаполнено(Выборка.Автор)
			И ДатыПоАвторам[Выборка.Автор] = Неопределено Тогда
			ДатыПоАвторам[Выборка.Автор] = Выборка.Дата;
		КонецЕсли;

	КонецЦикла;

	Возврат ДатыПоАвторам;

КонецФункции

// Добавляет в таблицу задачи-исполнители бизнес-процесса и комментарии проверок.
//
// Параметры:
//  Таблица - ТаблицаЗначений - таблица процессов и задач, дополняется.
//  БизнесПроцесс - БизнесПроцессСсылка.Исполнение - процесс.
//  ДатыВыполненияПоАвторам - Соответствие - даты выполнения по авторам.
//
Процедура ДобавитьЗадачиИсполнителиВТаблицу(Таблица, БизнесПроцесс, ДатыВыполненияПоАвторам)

	ЗапросИсполнителей = Новый Запрос;
	ЗапросИсполнителей.Текст =
		"ВЫБРАТЬ
		|	Исполнители.Исполнитель КАК Исполнитель,
		|	Исполнители.НаименованиеЗадачи КАК НаименованиеЗадачи,
		|	Исполнители.СрокИсполнения КАК СрокИсполнения,
		|	Исполнители.ИдентификаторИсполнителя КАК ИдентификаторИсполнителя
		|ИЗ
		|	БизнесПроцесс.Исполнение.Исполнители КАК Исполнители
		|ГДЕ
		|	Исполнители.Ссылка = &БизнесПроцесс
		|УПОРЯДОЧИТЬ ПО
		|	НаименованиеЗадачи";
	ЗапросИсполнителей.УстановитьПараметр("БизнесПроцесс", БизнесПроцесс);

	ЗапросПроверок = Новый Запрос;
	ЗапросПроверок.Текст =
		"ВЫБРАТЬ
		|	РезультатыПроверки.ОтправленоНаДоработку КАК ОтправленоНаДоработку,
		|	РезультатыПроверки.КомментарийПроверяющего КАК КомментарийПроверяющего,
		|	РезультатыПроверки.ИдентификаторИсполнителя КАК ИдентификаторИсполнителя
		|ИЗ
		|	БизнесПроцесс.Исполнение.РезультатыПроверки КАК РезультатыПроверки
		|ГДЕ
		|	РезультатыПроверки.Ссылка = &БизнесПроцесс";
	ЗапросПроверок.УстановитьПараметр("БизнесПроцесс", БизнесПроцесс);

	КомментарииПоИсполнителям = Новый Соответствие;
	ВыборкаПроверок = ЗапросПроверок.Выполнить().Выбрать();
	Пока ВыборкаПроверок.Следующий() Цикл
		Комментарий = СокрЛП(ВыборкаПроверок.КомментарийПроверяющего);
		Если Не ЗначениеЗаполнено(Комментарий) Тогда
			Продолжить;
		КонецЕсли;
		КлючИсполнителя = ВыборкаПроверок.ИдентификаторИсполнителя;
		Если КомментарииПоИсполнителям[КлючИсполнителя] = Неопределено Тогда
			КомментарииПоИсполнителям[КлючИсполнителя] = Комментарий;
		КонецЕсли;
	КонецЦикла;

	ВыборкаИсполнителей = ЗапросИсполнителей.Выполнить().Выбрать();
	Пока ВыборкаИсполнителей.Следующий() Цикл

		Строка = Таблица.Добавить();
		Строка.Уровень = 1;
		Строка.ЭтоЗадача = Истина;

		НаименованиеЗадачи = СокрЛП(Строка(ВыборкаИсполнителей.НаименованиеЗадачи));
		Строка.ПроцессЗадача = ?(ЗначениеЗаполнено(НаименованиеЗадачи),
			НаименованиеЗадачи, НСтр("ru = 'Задача исполнителя'"));

		Строка.Исполнитель = СокрЛП(Строка(ВыборкаИсполнителей.Исполнитель));

		Если ЗначениеЗаполнено(ВыборкаИсполнителей.СрокИсполнения) Тогда
			Строка.Срок = Формат(ВыборкаИсполнителей.СрокИсполнения, "ДФ='dd.MM.yyyy HH:mm'");
		КонецЕсли;

		ДатаВыполнения = ДатыВыполненияПоАвторам[ВыборкаИсполнителей.Исполнитель];
		Если ЗначениеЗаполнено(ДатаВыполнения) Тогда
			Строка.ДатаВыполнения = Формат(ДатаВыполнения, "ДФ='dd.MM.yyyy HH:mm'"); Строка.Дата = ДатаВыполнения;
		КонецЕсли;

		Строка.Комментарий = КомментарииПоИсполнителям[ВыборкаИсполнителей.ИдентификаторИсполнителя];

	КонецЦикла;

КонецПроцедуры

// Добавляет в таблицу подзадачи задачи и их действия.
//
// Параметры:
//  Таблица - ТаблицаЗначений - таблица процессов и задач, дополняется.
//  Задача - ДокументСсылка.Задача - задача.
//
Процедура ДобавитьПодзадачиВТаблицу(Таблица, Задача)

	Для Каждого Подзадача Из ДочерниеЗадачи(Задача) Цикл

		РеквизитыПодзадачи = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(
			Подзадача, "Заголовок, Автор, ДатаСоздания, Срок, ДатаВыполнения, Описание");

		Строка = Таблица.Добавить();
		Строка.Уровень = 1;
		Строка.ЭтоЗадача = Истина;
		Строка.ПроцессЗадача = СокрЛП(Строка(РеквизитыПодзадачи.Заголовок));
		Строка.Исполнитель = ПредставлениеУчастника(РеквизитыПодзадачи.Автор);

		Если ЗначениеЗаполнено(РеквизитыПодзадачи.Срок) Тогда
			Строка.Срок = Формат(РеквизитыПодзадачи.Срок, "ДФ='dd.MM.yyyy HH:mm'");
		КонецЕсли;
		Если ЗначениеЗаполнено(РеквизитыПодзадачи.ДатаВыполнения) Тогда
			Строка.ДатаВыполнения = Формат(РеквизитыПодзадачи.ДатаВыполнения, "ДФ='dd.MM.yyyy HH:mm'"); Строка.Дата = РеквизитыПодзадачи.ДатаВыполнения;
		КонецЕсли;

		Строка.Комментарий = СокрЛП(Строка(РеквизитыПодзадачи.Описание));

		ДобавитьДействияВТаблицу(Таблица, Подзадача, РеквизитыПодзадачи.Автор);

	КонецЦикла;

КонецПроцедуры

// Добавляет в таблицу действия подзадачи.
//
// Параметры:
//  Таблица - ТаблицаЗначений - таблица процессов и задач, дополняется.
//  Подзадача - ДокументСсылка.Задача - подзадача.
//  АвторПодзадачи - ОпределяемыйТип.УчастникЗадач - автор подзадачи.
//
Процедура ДобавитьДействияВТаблицу(Таблица, Подзадача, АвторПодзадачи, УровеньДействий = 2)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ
		|	ДействиеЗадачи.ДатаНачала КАК ДатаНачала,
		|	ДействиеЗадачи.ДатаВыполнения КАК ДатаВыполнения,
		|	ДействиеЗадачи.ОсобыйАвтор КАК ОсобыйАвтор,
		|	ДействиеЗадачи.Исполнитель КАК Исполнитель,
		|	ДействиеЗадачи.ФактическийИсполнитель КАК ФактическийИсполнитель,
		|	ДействиеЗадачи.СостояниеУчастникаЗадачи КАК СостояниеУчастникаЗадачи,
		|	ДействиеЗадачи.РезультатДействия КАК РезультатДействия,
		|	ДействиеЗадачи.РезультатДействияТекстом КАК РезультатДействияТекстом
		|ИЗ
		|	Документ.ДействиеЗадачи КАК ДействиеЗадачи
		|ГДЕ
		|	ДействиеЗадачи.Задача = &Задача
		|УПОРЯДОЧИТЬ ПО
		|	ДатаНачала ВОЗР,
		|	ДатаВыполнения ВОЗР";
	Запрос.УстановитьПараметр("Задача", Подзадача);

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл

		Автор = ?(ЗначениеЗаполнено(Выборка.ОсобыйАвтор), Выборка.ОсобыйАвтор, АвторПодзадачи);
		Адресат = ?(ЗначениеЗаполнено(Выборка.ФактическийИсполнитель),
			Выборка.ФактическийИсполнитель, Выборка.Исполнитель);
		Дата = ?(ЗначениеЗаполнено(Выборка.ДатаВыполнения), Выборка.ДатаВыполнения, Выборка.ДатаНачала);

		СостояниеДействия = СокрЛП(Строка(Выборка.СостояниеУчастникаЗадачи));
		ТекстРезультата = ТекстРезультатаДействия(Выборка);

		// Технические записи о создании действия не показываем.
		Если Не ЗначениеЗаполнено(СостояниеДействия)
			И Не ЗначениеЗаполнено(ТекстРезультата) Тогда
			Продолжить;
		КонецЕсли;
		Если Найти(СостояниеДействия, "Новая") > 0
			И Не ЗначениеЗаполнено(ТекстРезультата) Тогда
			Продолжить;
		КонецЕсли;

		Строка = Таблица.Добавить();
		Строка.Уровень = УровеньДействий;
		Строка.ПроцессЗадача = ЗаголовокЭтапа(Дата, Автор, Адресат, СостояниеДействия);

		Если ЗначениеЗаполнено(Дата) Тогда
			Строка.ДатаВыполнения = Формат(Дата, "ДФ='dd.MM.yyyy HH:mm'");
			Строка.Дата = Дата;
		КонецЕсли;

		Строка.Комментарий = ТекстРезультата;

	КонецЦикла;

КонецПроцедуры
// Возвращает узлы ленты по данным таблицы "Все процессы и задачи":
// задачи-исполнители, задачи по предмету и их этапы с исполнителями, сроками и комментариями.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Массив - узлы схемы жизненного цикла.
//
Функция УзлыИзТаблицыПроцессовИЗадач(Задача)

	Результат = Новый Массив;

	Таблица = ТаблицаПроцессовИЗадач(Задача);

	Для Каждого Строка Из Таблица Цикл

		// Процесс и этапы уже показаны типовой схемой жизненного цикла - оставляем только задачи.
		Если Не Строка.ЭтоЗадача Тогда
			Продолжить;
		КонецЕсли;

		Узел = РаботаСЗадачами.ЭлементСхемыЖизненногоЦикла();
		Узел.ТипУзла = Перечисления.ТипыУзловЖизненногоЦикла.ПромежуточныйУзел;
		Узел.ХарактерРезультата = Перечисления.ХарактерыРезультатов.Нейтральный;
		Узел.Дата = ?(ЗначениеЗаполнено(Строка.Дата), Строка.Дата, Дата(1, 1, 1));
		Узел.Заголовок = Строка.ПроцессЗадача;

		Части = Новый Массив;
		Если ЗначениеЗаполнено(Строка.Исполнитель) Тогда
			Части.Добавить(Строка.Исполнитель);
		КонецЕсли;
		Если ЗначениеЗаполнено(Строка.Срок) Тогда
			Части.Добавить(НСтр("ru = 'Срок: '") + Строка.Срок);
		КонецЕсли;
		Если ЗначениеЗаполнено(Строка.Комментарий) Тогда
			Части.Добавить(Строка.Комментарий);
		КонецЕсли;

		// Комментарий исполнения показываем полностью, с переносами по ширине панели.
		Узел.Описание = ТекстПоШирине(СтрСоединить(Части, "; "));

		Узел.Вставить("СтрокиЗаголовка", СтрЧислоСтрок(Узел.Заголовок));
		Узел.Вставить("СтрокиОписания", СтрЧислоСтрок(Узел.Описание));

		Результат.Добавить(Узел);

	КонецЦикла;

	Возврат Результат;

КонецФункции

// Дополняет список задач всеми подзадачами, вопросами и ознакомлениями по действиям задач.
// Обход рекурсивный: подзадачи задач, подзадачи по действиям, пока не закончатся.
//
// Параметры:
//  Задачи - Массив - задачи, дополняется найденными подзадачами.
//
Процедура СобратьПотомковЗадач(Задачи)

	Очередь = Новый Массив;
	Для Каждого Задача Из Задачи Цикл
		Очередь.Добавить(Задача);
	КонецЦикла;

	Обработано = 0;
	Пока Очередь.Количество() > 0 И Обработано < 200 Цикл

		ТекущаяЗадача = Очередь[0];
		Очередь.Удалить(0);
		Обработано = Обработано + 1;

		Найденные = Документы.Задача.НайтиПодзадачи(
			ОбщегоНазначенияКлиентСервер.ЗначениеВМассиве(ТекущаяЗадача));

		Действия = ДействияЗадачиСсылки(ТекущаяЗадача);
		Если Действия.Количество() > 0 Тогда
			ДобавитьБезПовторов(Найденные, Документы.ДействиеЗадачи.НайтиПодзадачи(Действия));
		КонецЕсли;

		Для Каждого Подзадача Из Найденные Цикл
			Если Задачи.Найти(Подзадача) = Неопределено Тогда
				Задачи.Добавить(Подзадача);
				Очередь.Добавить(Подзадача);
			КонецЕсли;
		КонецЦикла;

	КонецЦикла;

КонецПроцедуры

// Возвращает все бизнес-процессы по предмету: исполнение, ознакомление, согласование,
// утверждение, регистрация, приглашение.
//
// Параметры:
//  Предмет - Произвольный - предмет (документ, протокол и т.п.).
//
// Возвращаемое значение:
//  Массив - бизнес-процессы разных типов.
//
Функция БизнесПроцессыПоПредмету(Предмет)

	Результат = Новый Массив;
	Если Не ЗначениеЗаполнено(Предмет) Тогда
		Возврат Результат;
	КонецЕсли;

	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Исполнение.Предметы");
	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Ознакомление.Предметы");
	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Согласование.Предметы");
	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Утверждение.Предметы");
	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Регистрация.Предметы");
	ДобавитьПроцессыПоПредмету(Результат, Предмет, "БизнесПроцесс.Приглашение.Предметы");

	Возврат Результат;

КонецФункции

// Добавляет процессы одного типа по предмету.
//
// Параметры:
//  Результат - Массив - накопительный список процессов, дополняется.
//  Предмет - Произвольный - предмет.
//  ИмяТаблицы - Строка - полное имя таблицы предметов процесса.
//
Процедура ДобавитьПроцессыПоПредмету(Результат, Предмет, ИмяТаблицы)

	Запрос = Новый Запрос(
		"ВЫБРАТЬ
		|	Предметы.Ссылка КАК Ссылка
		|ИЗ
		|	" + ИмяТаблицы + " КАК Предметы
		|ГДЕ
		|	Предметы.Предмет = &Предмет");
	Запрос.УстановитьПараметр("Предмет", Предмет);

