// Возвращает задачи-исполнители бизнес-процесса.
//
// Параметры:
//  БизнесПроцесс - БизнесПроцессСсылка - процесс.
//
// Возвращаемое значение:
//  ТаблицаЗначений:
//   * Задача - ЗадачаСсылка.ЗадачаИсполнителя - задача-исполнитель;
//   * Исполнитель - Строка - исполнитель;
//   * Срок - Строка - срок исполнения.
//
Функция ЗадачиИсполнителиПроцесса(БизнесПроцесс)

	Результат = Новый ТаблицаЗначений;
	Результат.Колонки.Добавить("Задача");
	Результат.Колонки.Добавить("Исполнитель", Новый ОписаниеТипов("Строка"));
	Результат.Колонки.Добавить("Срок", Новый ОписаниеТипов("Строка"));

	ИмяТаблицы = "";

	Если ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Утверждение") Тогда
		ИмяТаблицы = "БизнесПроцесс.Утверждение.РезультатыУтверждения";
	ИначеЕсли ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Регистрация") Тогда
		ИмяТаблицы = "БизнесПроцесс.Регистрация.РезультатыРегистрации";
	Иначе
		ИмяТаблицы = "БизнесПроцесс.Исполнение.Исполнители";
		Если ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Ознакомление") Тогда
			ИмяТаблицы = "БизнесПроцесс.Ознакомление.Исполнители";
		ИначеЕсли ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Согласование") Тогда
			ИмяТаблицы = "БизнесПроцесс.Согласование.Исполнители";
		ИначеЕсли ТипЗнч(БизнесПроцесс) = Тип("БизнесПроцессСсылка.Приглашение") Тогда
			ИмяТаблицы = "БизнесПроцесс.Приглашение.Исполнители";
		КонецЕсли;
	КонецЕсли;

	ТекстЗапроса =
		"ВЫБРАТЬ
		|	Задачи.ЗадачаИсполнителя КАК Задача
		|ИЗ
		|	" + ИмяТаблицы + " КАК Задачи
		|ГДЕ
		|	Задачи.Ссылка = &БизнесПроцесс";

	Запрос = Новый Запрос(ТекстЗапроса);
	Запрос.УстановитьПараметр("БизнесПроцесс", БизнесПроцесс);

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл

		Если Не ЗначениеЗаполнено(Выборка.Задача) Тогда
			Продолжить;
		КонецЕсли;

		Строка = Результат.Добавить();
		Строка.Задача = Выборка.Задача;
		Строка.Исполнитель = СокрЛП(Строка(Выборка.Задача.Исполнитель));

	КонецЦикла;

	Возврат Результат;

