//
Функция РодителиЗадачИсполнителей(ЗадачиИсполнители)

	Родители = Новый Соответствие;

	Если ЗадачиИсполнители.Количество() = 0 Тогда
		Возврат Родители;
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ
		|	ДействиеЗадачи.Источник КАК Источник,
		|	ДействиеЗадачи.Задача КАК Задача
		|ИЗ
		|	Документ.ДействиеЗадачи КАК ДействиеЗадачи
		|ГДЕ
		|	ДействиеЗадачи.Источник В(&Задачи)";
	Запрос.УстановитьПараметр("Задачи", ЗадачиИсполнители);

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл
		Родители[Выборка.Источник] = Выборка.Задача;
	КонецЦикла;

