		Уровень,
		СтрШаблон(НСтр("ru = 'Процесс: %1'"), Данные.Наименование),
		"",
		Данные.Дата,
		Данные.СрокИсполнения,
		Данные.ДатаЗавершения,
		ХарактерРезультатаПоДате(Данные.ДатаЗавершения, Ложь),
		Процесс));
	Контекст.Количество = Контекст.Количество + 1;

	Для Каждого ЗадачаИсполнителя Из ЗадачиИсполнителиПроцесса(Процесс) Цикл
		ДобавитьЗадачуИсполнителя(ЗадачаИсполнителя, Уровень + 1, Узлы, Контекст);
	КонецЦикла;

КонецПроцедуры

// Добавляет в узлы задачу-исполнителя процесса и вложенные в нее процессы.
//
// Параметры:
//  Задача - ЗадачаСсылка.ЗадачаИсполнителя - задача-исполнитель процесса.
//  Уровень - Число - уровень вложенности.
//  Узлы - Массив - накопительный список узлов, дополняется.
//  Контекст - Структура - контекст построения, см. СхемаПолнойИстории.
//
Процедура ДобавитьЗадачуИсполнителя(Задача, Уровень, Узлы, Контекст)

	Если Контекст.Обработанные[Задача] <> Неопределено
		Или ОбходЗавершен(Уровень, Контекст) Тогда
		Возврат;
	КонецЕсли;
	Контекст.Обработанные[Задача] = Истина;

	Данные = ДанныеЗадачиИсполнителя(Задача);

	Узлы.Добавить(НовыйУзелИстории(
		Уровень,
		Данные.Наименование,
		Данные.Исполнитель,
		Данные.Дата,
		Данные.Срок,
		Данные.ДатаВыполнения,
		ХарактерРезультатаПоДате(Данные.ДатаВыполнения, Данные.Отменена),
		Задача));
	Контекст.Количество = Контекст.Количество + 1;

	// Ознакомление с исполнением, вопросы и прочие процессы по этой задаче-исполнителю.
	Для Каждого Процесс Из ПроцессыПоПредмету(Задача) Цикл
		ДобавитьПроцесс(Процесс, Уровень + 1, Узлы, Контекст);
	КонецЦикла;

КонецПроцедуры

// Добавляет в узлы задачу (поручение), процессы по ней и ее подзадачи.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//  Уровень - Число - уровень вложенности.
//  Узлы - Массив - накопительный список узлов, дополняется.
//  Контекст - Структура - контекст построения, см. СхемаПолнойИстории.
//
Процедура ДобавитьЗадачу(Задача, Уровень, Узлы, Контекст)

	Если Контекст.Обработанные[Задача] <> Неопределено
		Или ОбходЗавершен(Уровень, Контекст) Тогда
		Возврат;
	КонецЕсли;
	Контекст.Обработанные[Задача] = Истина;

	Данные = ДанныеЗадачи(Задача);

	Узлы.Добавить(НовыйУзелИстории(
		Уровень,
		Данные.Заголовок,
		Данные.Исполнитель,
		Данные.Дата,
		Данные.Срок,
		Данные.ДатаВыполнения,
		ХарактерРезультатаПоДате(Данные.ДатаВыполнения, Данные.Отменена),
		Задача));
	Контекст.Количество = Контекст.Количество + 1;

	// Согласование, утверждение, ознакомление и прочие процессы по этой задаче.
	Для Каждого Процесс Из ПроцессыПоПредмету(Задача) Цикл
		ДобавитьПроцесс(Процесс, Уровень + 1, Узлы, Контекст);
	КонецЦикла;

	// Подзадачи и поручения по задаче и по ее действиям.
	Для Каждого Подзадача Из ПодзадачиЗадачи(Задача) Цикл
		ДобавитьЗадачу(Подзадача, Уровень + 1, Узлы, Контекст);
	КонецЦикла;

КонецПроцедуры

// Возвращает предмет (приложение) задачи, по которому строится полная история.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Произвольный - предмет задачи или Неопределено.
//
Функция ПредметЗадачи(Задача)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ
		|	ЗадачаПриложения.Приложение КАК Приложение
		|ИЗ
		|	Документ.Задача.Приложения КАК ЗадачаПриложения
		|ГДЕ
		|	ЗадачаПриложения.Ссылка = &Задача
		|УПОРЯДОЧИТЬ ПО
		|	ЗадачаПриложения.НомерСтроки";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл
		Если ЗначениеЗаполнено(Выборка.Приложение) Тогда
			Возврат Выборка.Приложение;
		КонецЕсли;
	КонецЦикла;

	// Предмет процесса, в рамках которого создана задача.
	Источник = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Задача, "Источник");
	Если ЗначениеЗаполнено(Источник)
		И ОбщегоНазначения.ЭтоБизнесПроцесс(Источник.Метаданные()) Тогда
		Предмет = ПредметПроцесса(Источник);
		Если ЗначениеЗаполнено(Предмет) Тогда
			Возврат Предмет;
		КонецЕсли;
	КонецЕсли;

	Возврат Неопределено;

КонецФункции

// Возвращает первый предмет бизнес-процесса.
//
// Параметры:
//  Процесс - БизнесПроцессСсылка - бизнес-процесс.
//
// Возвращаемое значение:
//  Произвольный - предмет процесса или Неопределено.
//
Функция ПредметПроцесса(Процесс)

	Если Процесс.Метаданные().ТабличныеЧасти.Найти("Предметы") = Неопределено Тогда
		Возврат Неопределено;
	КонецЕсли;

	Запрос = Новый Запрос(
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ ПЕРВЫЕ 1
		|	Предметы.Предмет КАК Предмет
		|ИЗ
		|	" + Процесс.Метаданные().ПолноеИмя() + ".Предметы КАК Предметы
		|ГДЕ
		|	Предметы.Ссылка = &Процесс");
	Запрос.УстановитьПараметр("Процесс", Процесс);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() И ЗначениеЗаполнено(Выборка.Предмет) Тогда
		Возврат Выборка.Предмет;
	КонецЕсли;

	Возврат Неопределено;

КонецФункции

// Возвращает все бизнес-процессы, у которых предмет совпадает с указанным объектом.
//
// Параметры:
//  Предмет - Произвольный - предмет (документ, файл, задача и т. п.).
//
// Возвращаемое значение:
//  Массив - бизнес-процессы, упорядоченные по дате.
//
Функция ПроцессыПоПредмету(Предмет)

	Результат = Новый Массив;
	Если Не ЗначениеЗаполнено(Предмет) Тогда
		Возврат Результат;
	КонецЕсли;

	ТекстЗапроса = "";
	Для Каждого МетаданныеПроцесса Из Метаданные.БизнесПроцессы Цикл

		Если МетаданныеПроцесса.ТабличныеЧасти.Найти("Предметы") = Неопределено Тогда
			Продолжить;
		КонецЕсли;

		Если ТекстЗапроса <> "" Тогда
			ТекстЗапроса = ТекстЗапроса + Символы.ПС + "ОБЪЕДИНИТЬ ВСЕ" + Символы.ПС;
		КонецЕсли;

		ТекстЗапроса = ТекстЗапроса
			+ "ВЫБРАТЬ Предметы.Ссылка КАК Ссылка ИЗ "
			+ МетаданныеПроцесса.ПолноеИмя() + ".Предметы КАК Предметы"
			+ " ГДЕ Предметы.Предмет = &Предмет";

	КонецЦикла;

	Если ТекстЗапроса = "" Тогда
		Возврат Результат;
	КонецЕсли;

	Запрос = Новый Запрос("ВЫБРАТЬ РАЗРЕШЕННЫЕ Ссылка КАК Ссылка ИЗ (ВЫБРАТЬ ...)");
	Запрос.Текст = "ВЫБРАТЬ РАЗРЕШЕННЫЕ Процессы.Ссылка КАК Ссылка ИЗ (" + ТекстЗапроса + ") КАК Процессы";
	Запрос.УстановитьПараметр("Предмет", Предмет);

	Попытка
		Результат = Запрос.Выполнить().Выгрузить().ВыгрузитьКолонку("Ссылка");
	Исключение
		Результат = ПроцессыПоПредметуПоТипам(Предмет);
	КонецПопытки;

	Возврат УпорядочитьПроцессыПоДате(Результат);

КонецФункции

// Возвращает процессы по предмету отдельными запросами по каждому типу процесса.
// Используется, если общий запрос по всем типам процессов не выполнился.
//
// Параметры:
//  Предмет - Произвольный - предмет.
//
// Возвращаемое значение:
//  Массив - бизнес-процессы.
//
Функция ПроцессыПоПредметуПоТипам(Предмет)

	Результат = Новый Массив;

	Для Каждого МетаданныеПроцесса Из Метаданные.БизнесПроцессы Цикл

		Если МетаданныеПроцесса.ТабличныеЧасти.Найти("Предметы") = Неопределено Тогда
			Продолжить;
		КонецЕсли;

		Запрос = Новый Запрос(
			"ВЫБРАТЬ РАЗРЕШЕННЫЕ
			|	Предметы.Ссылка КАК Ссылка
			|ИЗ
			|	" + МетаданныеПроцесса.ПолноеИмя() + ".Предметы КАК Предметы
			|ГДЕ
			|	Предметы.Предмет = &Предмет");
		Запрос.УстановитьПараметр("Предмет", Предмет);

		Попытка
			Выборка = Запрос.Выполнить().Выбрать();
			Пока Выборка.Следующий() Цикл
				Результат.Добавить(Выборка.Ссылка);
			КонецЦикла;
		Исключение
			// Тип предмета не подходит для этого процесса - пропускаем.
			Продолжить;
		КонецПопытки;

	КонецЦикла;

	Возврат Результат;

КонецФункции

// Возвращает задачи-исполнители бизнес-процесса.
//
// Параметры:
//  Процесс - БизнесПроцессСсылка - бизнес-процесс.
//
// Возвращаемое значение:
//  Массив - задачи-исполнители, упорядоченные по дате.
//
Функция ЗадачиИсполнителиПроцесса(Процесс)

	Задачи = РаботаСБизнесПроцессами.ВсеЗадачиИсполнителейПроцесса(Процесс);
	Возврат УпорядочитьПоДате(Задачи);

КонецФункции

// Возвращает задачи по приложению (предмету).
//
// Параметры:
//  Предмет - Произвольный - предмет (документ, файл и т. п.).
//
// Возвращаемое значение:
//  Массив - задачи, упорядоченные по дате.
//
Функция ЗадачиПоПриложению(Предмет)

	Задачи = РаботаСЗадачами.ЗадачиПоПриложению(Предмет, Истина);
	Возврат УпорядочитьПоДате(Задачи);

КонецФункции

// Возвращает подзадачи задачи и задачи, созданные по ее действиям.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Массив - подзадачи, упорядоченные по дате.
//
Функция ПодзадачиЗадачи(Задача)

	Результат = Новый Массив;

	ОбщегоНазначенияКлиентСервер.ДополнитьМассив(
		Результат, Документы.Задача.НайтиПодзадачи(ОбщегоНазначенияКлиентСервер.ЗначениеВМассиве(Задача)));

	Действия = ДействияЗадачи(Задача);
	Если Действия.Количество() > 0 Тогда
		ОбщегоНазначенияКлиентСервер.ДополнитьМассив(
			Результат, Документы.ДействиеЗадачи.НайтиПодзадачи(Действия));
	КонецЕсли;

	Возврат УпорядочитьПоДате(Результат);

КонецФункции

// Возвращает действия задачи.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Массив - действия задачи.
//
Функция ДействияЗадачи(Задача)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ
		|	ДействиеЗадачи.Ссылка КАК Ссылка
		|ИЗ
		|	Документ.ДействиеЗадачи КАК ДействиеЗадачи
		|ГДЕ
		|	ДействиеЗадачи.Задача = &Задача";
	Запрос.УстановитьПараметр("Задача", Задача);

	Возврат Запрос.Выполнить().Выгрузить().ВыгрузитьКолонку("Ссылка");

КонецФункции

// Проверяет, есть ли у задачи вышестоящая задача или вышестоящее действие.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Булево - Истина, если задача вложенная.
//
Функция РодительскаяЗадачаЗаполнена(Задача)

	Реквизиты = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(
		Задача, "ВышестоящаяЗадача, ВышестоящееДействие");

	Возврат ЗначениеЗаполнено(Реквизиты.ВышестоящаяЗадача)
		Или ЗначениеЗаполнено(Реквизиты.ВышестоящееДействие);

КонецФункции

// Возвращает данные процесса для узла истории.
//
// Параметры:
//  Процесс - БизнесПроцессСсылка - бизнес-процесс.
//
// Возвращаемое значение:
//  Структура:
//   * Наименование - Строка - наименование процесса;
//   * Дата - Дата - дата процесса;
//   * СрокИсполнения - Дата - срок исполнения;
//   * ДатаЗавершения - Дата - дата завершения.
//
Функция ДанныеПроцесса(Процесс)

	Результат = Новый Структура;
	Результат.Вставить("Наименование", СокрЛП(Строка(Процесс)));
	Результат.Вставить("Дата", Неопределено);
	Результат.Вставить("СрокИсполнения", Неопределено);
	Результат.Вставить("ДатаЗавершения", Неопределено);

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ
		|	Данные.Наименование КАК Наименование,
		|	Данные.Дата КАК Дата,
		|	Данные.СрокИсполнения КАК СрокИсполнения,
		|	Данные.ДатаЗавершения КАК ДатаЗавершения
		|ИЗ
		|	РегистрСведений.ДанныеБизнесПроцессов КАК Данные
		|ГДЕ
		|	Данные.БизнесПроцесс = &Процесс
		|УПОРЯДОЧИТЬ ПО
		|	Данные.Завершен УБЫВ";
	Запрос.УстановитьПараметр("Процесс", Процесс);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() Тогда
		Если ЗначениеЗаполнено(Выборка.Наименование) Тогда
			Результат.Наименование = СокрЛП(Выборка.Наименование);
		КонецЕсли;
		Результат.Дата = Выборка.Дата;
		Результат.СрокИсполнения = Выборка.СрокИсполнения;
		Результат.ДатаЗавершения = Выборка.ДатаЗавершения;
	КонецЕсли;

	Если Не ЗначениеЗаполнено(Результат.Дата) Тогда
		Результат.Дата = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Процесс, "Дата");
	КонецЕсли;

	Возврат Результат;

КонецФункции

// Возвращает данные задачи-исполнителя процесса для узла истории.
//
// Параметры:
//  Задача - ЗадачаСсылка.ЗадачаИсполнителя - задача-исполнитель.
//
// Возвращаемое значение:
//  Структура:
//   * Наименование - Строка - наименование задачи;
//   * Исполнитель - Строка - представление исполнителя;
//   * Дата - Дата - дата поступления задачи исполнителю;
//   * Срок - Дата - срок исполнения;
//   * ДатаВыполнения - Дата - дата выполнения;
//   * Отменена - Булево - задача отменена.
//
Функция ДанныеЗадачиИсполнителя(Задача)

	Реквизиты = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(Задача,
		"Дата, Наименование, ТекущийИсполнитель, ФактическийИсполнитель,
		|СрокИсполнения, Выполнена, ДатаИсполнения, Отменена");

	Исполнитель = ?(Реквизиты.Выполнена = Истина
			И ЗначениеЗаполнено(Реквизиты.ФактическийИсполнитель),
		Реквизиты.ФактическийИсполнитель,
		Реквизиты.ТекущийИсполнитель);

	Результат = Новый Структура;
	Результат.Вставить("Наименование", СокрЛП(Строка(Реквизиты.Наименование)));
	Результат.Вставить("Исполнитель", СокрЛП(Строка(Исполнитель)));
	Результат.Вставить("Дата", Реквизиты.Дата);
	Результат.Вставить("Срок", Реквизиты.СрокИсполнения);
	Результат.Вставить("ДатаВыполнения", Реквизиты.ДатаИсполнения);
	Результат.Вставить("Отменена", Реквизиты.Отменена = Истина);

	Возврат Результат;

КонецФункции

// Возвращает данные задачи (поручения) для узла истории.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//
// Возвращаемое значение:
//  Структура:
//   * Заголовок - Строка - заголовок задачи;
//   * Исполнитель - Строка - представление исполнителя;
//   * Дата - Дата - дата поступления задачи исполнителю;
//   * Срок - Дата - срок исполнения;
//   * ДатаВыполнения - Дата - дата выполнения;
//   * Отменена - Булево - задача отменена.
//
Функция ДанныеЗадачи(Задача)

	Реквизиты = ОбщегоНазначения.ЗначенияРеквизитовОбъекта(Задача,
		"Дата, Заголовок, Срок, ДатаВыполнения, ДатаОтмены, Автор");

	Результат = Новый Структура;
	Результат.Вставить("Заголовок", СокрЛП(Строка(Реквизиты.Заголовок)));
	Результат.Вставить("Исполнитель", ПредставлениеИсполнителя(Задача, Реквизиты.Автор));
	Результат.Вставить("Дата", Реквизиты.Дата);
	Результат.Вставить("Срок", Реквизиты.Срок);
	Результат.Вставить("ДатаВыполнения", Реквизиты.ДатаВыполнения);
	Результат.Вставить("Отменена", ЗначениеЗаполнено(Реквизиты.ДатаОтмены));

	Возврат Результат;

КонецФункции

// Возвращает представление исполнителя задачи: участника с видом "исполнитель" или автора.
//
// Параметры:
//  Задача - ДокументСсылка.Задача - задача.
//  Автор - ОпределяемыйТип.УчастникЗадач - автор задачи.
//
// Возвращаемое значение:
//  Строка - представление исполнителя.
//
Функция ПредставлениеИсполнителя(Задача, Автор)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ ПЕРВЫЕ 1
		|	Участники.Участник КАК Участник
		|ИЗ
		|	Документ.Задача.Участники КАК Участники
		|		ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.ВидыУчастниковЗадач КАК Виды
		|		ПО Участники.ВидУчастника = Виды.Ссылка
		|ГДЕ
		|	Участники.Ссылка = &Задача
		|	И Виды.ЭтоИсполнитель = ИСТИНА
		|УПОРЯДОЧИТЬ ПО
		|	Участники.НомерСтроки";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() И ЗначениеЗаполнено(Выборка.Участник) Тогда
		Возврат СокрЛП(РаботаСЗадачамиПовтИсп.ПредставлениеУчастника(Выборка.Участник, Истина));
	КонецЕсли;

	Возврат СокрЛП(Строка(Автор));

КонецФункции

// Создает узел истории с иерархическим отступом и расшифровкой исполнителя и дат.
//
// Параметры:
//  Уровень - Число - уровень вложенности;
//  Заголовок - Строка - заголовок узла;
//  Исполнитель - Строка - представление исполнителя;
//  ДатаПоступления - Дата - дата поступления задачи исполнителю;
//  Срок - Дата - срок исполнения;
//  ДатаВыполнения - Дата - дата выполнения;
//  Характер - ПеречислениеСсылка.ХарактерыРезультатов - характер результата узла;
//  Ссылка - Произвольный - объект истории.
//
// Возвращаемое значение:
//  Структура - узел схемы жизненного цикла.
//
Функция НовыйУзелИстории(Уровень, Заголовок, Исполнитель, ДатаПоступления, Срок, ДатаВыполнения,
	Характер, Ссылка)

	Узел = РаботаСЗадачами.ЭлементСхемыЖизненногоЦикла();
	Узел.ТипУзла = Перечисления.ТипыУзловЖизненногоЦикла.ПромежуточныйУзел;
	Узел.ХарактерРезультата = Характер;

	Если ЗначениеЗаполнено(ДатаПоступления) Тогда
		Узел.Дата = ДатаПоступления;
	КонецЕсли;

	Ширина = ШиринаСтрокиТекста() - Уровень * ШагОтступа();
	Если Ширина < 24 Тогда
		Ширина = 24;
	КонецЕсли;

	Отступ = СтрЗаменить(СтрШаблон("%1|", Уровень * ШагОтступа()), "|", "");
	Узел.Заголовок = СтрокиСТекстом(Заголовок, Ширина, Отступ);
	Узел.Описание = ОписаниеУзла(Исполнитель, ДатаПоступления, Срок, ДатаВыполнения, Ширина);

	Если ЗначениеЗаполнено(Ссылка) Тогда
		Узел.НавигационнаяСсылка = ПолучитьНавигационнуюСсылку(Ссылка);
	КонецЕсли;

	Возврат Узел;

КонецФункции

// Возвращает отступ уровня вложенности.
//
// Параметры:
//  Уровень - Число - уровень вложенности.
//
// Возвращаемое значение:
//  Строка - отступ из неразрывных пробелов.
//
Функция ОтступУровня(Уровень)

	Результат = "";
	Для НомерСимвола = 1 По Уровень * ШагОтступа() Цикл
		Результат = Результат + Символ(160);
	КонецЦикла;

	Возврат Результат;

КонецФункции

// Переносит текст по ширине и добавляет отступ в начало каждой строки.
//
// Параметры:
//  Текст - Строка - текст;
//  Ширина - Число - ширина строки в символах;
//  Отступ - Строка - отступ в начало каждой строки.
//
// Возвращаемое значение:
//  Строка - текст, разбитый на строки.
//
Функция СтрокиСТекстом(Текст, Ширина, Отступ)

	Результат = "";
	Для Каждого СтрокаТекста Из ПереносПоШирине(Текст, Ширина) Цикл
		Если Результат <> "" Тогда
			Результат = Результат + Символы.ПС;
		КонецЕсли;
		Результат = Результат + Отступ + СтрокаТекста;
	КонецЦикла;

	Возврат Результат;

КонецФункции

// Формирует описание узла: исполнитель, дата поступления, срок и дата выполнения.
//
// Параметры:
//  Исполнитель - Строка - представление исполнителя;
//  ДатаПоступления - Дата - дата поступления задачи исполнителю;
//  Срок - Дата - срок исполнения;
//  ДатаВыполнения - Дата - дата выполнения;
//  Ширина - Число - ширина строки в символах.
//
// Возвращаемое значение:
//  Строка - описание узла.
//
Функция ОписаниеУзла(Исполнитель, ДатаПоступления, Срок, ДатаВыполнения, Ширина)

	Части = Новый Массив;

	Если ЗначениеЗаполнено(Исполнитель) Тогда
		Части.Добавить(НСтр("ru = 'Исполнитель: '") + СокрЛП(Строка(Исполнитель)));
	КонецЕсли;

	СтрокаДат = "";
	Если ЗначениеЗаполнено(ДатаПоступления) Тогда
		СтрокаДат = НСтр("ru = 'Поступила: '") + Формат(ДатаПоступления, "ДФ='dd.MM.yyyy HH:mm'");
	КонецЕсли;
	Если ЗначениеЗаполнено(Срок) Тогда
		СтрокаСрока = НСтр("ru = 'срок: '") + Формат(Срок, "ДФ='dd.MM.yyyy HH:mm'");
		Если СтрокаДат = "" Тогда
			СтрокаДат = НСтр("ru = 'Срок: '") + Формат(Срок, "ДФ='dd.MM.yyyy HH:mm'");
		Иначе
			СтрокаДат = СтрокаДат + ", " + СтрокаСрока;
		КонецЕсли;
	КонецЕсли;
	Если СтрокаДат <> "" Тогда
		Части.Добавить(СтрокаДат);
	КонецЕсли;

	Если ЗначениеЗаполнено(ДатаВыполнения) Тогда
		Части.Добавить(НСтр("ru = 'Выполнена: '") + Формат(ДатаВыполнения, "ДФ='dd.MM.yyyy HH:mm'"));
	КонецЕсли;

	Результат = "";
	Для Каждого Часть Из Части Цикл
		Для Каждого СтрокаТекста Из ПереносПоШирине(Часть, Ширина) Цикл
			Если Результат <> "" Тогда
				Результат = Результат + Символы.ПС;
			КонецЕсли;
			Результат = Результат + СтрокаТекста;
		КонецЦикла;
	КонецЦикла;

	Возврат Результат;

КонецФункции

// Переносит текст на строки по ширине, не разрывая слова.
//
// Параметры:
//  Текст - Строка - текст;
//  Ширина - Число - ширина строки в символах.
//
// Возвращаемое значение:
//  Массив - строки текста.
//
Функция ПереносПоШирине(Текст, Ширина)

	Результат = Новый Массив;
	Остаток = СокрЛП(Строка(Текст));

	Пока СтрДлина(Остаток) > Ширина Цикл

		Позиция = Ширина;
		Пока Позиция > 1 И Сред(Остаток, Позиция, 1) <> " " Цикл
			Позиция = Позиция - 1;
		КонецЦикла;
		Если Позиция <= 1 Тогда
			Позиция = Ширина;
		КонецЕсли;

		Результат.Добавить(СокрЛП(Лев(Остаток, Позиция)));
		Остаток = СокрЛП(Сред(Остаток, Позиция + 1));

	КонецЦикла;

	Если Остаток <> "" Тогда
		Результат.Добавить(Остаток);
	КонецЕсли;

	Возврат Результат;

КонецФункции

// Возвращает характер результата узла по дате выполнения и признаку отмены.
//
// Параметры:
//  ДатаВыполнения - Дата - дата выполнения;
//  Отменена - Булево - объект отменен.
//
// Возвращаемое значение:
//  ПеречислениеСсылка.ХарактерыРезультатов - характер результата.
//
Функция ХарактерРезультатаПоДате(ДатаВыполнения, Отменена)

	Если Отменена = Истина Тогда
		Возврат Перечисления.ХарактерыРезультатов.Отрицательный;
	КонецЕсли;

	Если ЗначениеЗаполнено(ДатаВыполнения) Тогда
		Возврат Перечисления.ХарактерыРезультатов.Положительный;
	КонецЕсли;

	Возврат Перечисления.ХарактерыРезультатов.Нейтральный;

КонецФункции

// Упорядочивает объекты (задачи) по дате.
//
// Параметры:
//  Объекты - Массив - задачи одного типа.
//
// Возвращаемое значение:
//  Массив - упорядоченные объекты.
//
Функция УпорядочитьПоДате(Объекты)

	Если Объекты.Количество() < 2 Тогда
		Возврат Объекты;
	КонецЕсли;

	Реквизиты = ОбщегоНазначения.ЗначенияРеквизитовОбъектов(Объекты, "Дата");

	Таблица = Новый ТаблицаЗначений;
	Таблица.Колонки.Добавить("Объект");
	Таблица.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
	Таблица.Колонки.Добавить("Порядок", Новый ОписаниеТипов("Число"));

	Порядок = 0;
	Для Каждого Объект Из Объекты Цикл

		Строка = Таблица.Добавить();
		Строка.Объект = Объект;

		ДатаОбъекта = Реквизиты[Объект].Дата;
		Если Не ЗначениеЗаполнено(ДатаОбъекта) Тогда
			ДатаОбъекта = Дата(1, 1, 1);
		КонецЕсли;
		Строка.Дата = ДатаОбъекта;
		Строка.Порядок = Порядок;

		Порядок = Порядок + 1;

	КонецЦикла;

	Таблица.Сортировать("Дата, Порядок");

	Результат = Новый Массив;
	Для Каждого Строка Из Таблица Цикл
		Результат.Добавить(Строка.Объект);
	КонецЦикла;

	Возврат Результат;

КонецФункции

// Упорядочивает процессы по дате процесса.
//
// Параметры:
//  Процессы - Массив - бизнес-процессы.
//
// Возвращаемое значение:
//  Массив - упорядоченные процессы.
//
Функция УпорядочитьПроцессыПоДате(Процессы)

	Если Процессы.Количество() < 2 Тогда
		Возврат Процессы;
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ
		|	Данные.БизнесПроцесс КАК БизнесПроцесс,
		|	МИНИМУМ(Данные.Дата) КАК Дата
		|ИЗ
		|	РегистрСведений.ДанныеБизнесПроцессов КАК Данные
		|ГДЕ
		|	Данные.БизнесПроцесс В(&Процессы)
		|СГРУППИРОВАТЬ ПО
		|	Данные.БизнесПроцесс";
	Запрос.УстановитьПараметр("Процессы", Процессы);

	ДатыПроцессов = Новый Соответствие;
	Выборка = Запрос.Выполнить().Выбрать();
	Пока Выборка.Следующий() Цикл
		ДатыПроцессов[Выборка.БизнесПроцесс] = Выборка.Дата;
	КонецЦикла;

	Таблица = Новый ТаблицаЗначений;
	Таблица.Колонки.Добавить("Процесс");
	Таблица.Колонки.Добавить("Дата", Новый ОписаниеТипов("Дата"));
	Таблица.Колонки.Добавить("Порядок", Новый ОписаниеТипов("Число"));

	Порядок = 0;
	Для Каждого Процесс Из Процессы Цикл

		Строка = Таблица.Добавить();
		Строка.Процесс = Процесс;

		ДатаПроцесса = ДатыПроцессов[Процесс];
		Если Не ЗначениеЗаполнено(ДатаПроцесса) Тогда
			ДатаПроцесса = ОбщегоНазначения.ЗначениеРеквизитаОбъекта(Процесс, "Дата");
		КонецЕсли;
		Если Не ЗначениеЗаполнено(ДатаПроцесса) Тогда
			ДатаПроцесса = Дата(1, 1, 1);
		КонецЕсли;
		Строка.Дата = ДатаПроцесса;
		Строка.Порядок = Порядок;

		Порядок = Порядок + 1;

	КонецЦикла;

	Таблица.Сортировать("Дата, Порядок");

	Результат = Новый Массив;
	Для Каждого Строка Из Таблица Цикл
		Результат.Добавить(Строка.Процесс);
	КонецЦикла;

	Возврат Результат;

КонецФункции

