			ТекстЗапроса = ТекстЗапроса + " ОБЪЕДИНИТЬ ВСЕ ВЫБРАТЬ ";
		КонецЕсли;

		ТекстЗапроса = ТекстЗапроса
			+ "Предметы.Ссылка КАК Ссылка ИЗ "
			+ МетаданныеПроцесса.ПолноеИмя() + ".Предметы КАК Предметы"
			+ " ГДЕ Предметы.Предмет = &Предмет";

	КонецЦикла;

	Если ТекстЗапроса = "" Тогда
		Возврат Результат;
	КонецЕсли;

	Запрос = Новый Запрос("ВЫБРАТЬ РАЗРЕШЕННЫЕ " + ТекстЗапроса);
	Запрос.УстановитьПараметр("Предмет", Предмет);

