#Область ОбработчикиСобытийФормы

&НаСервере
&После("ПриСозданииНаСервере")
Процедура ПолнаяИсторияЗадач_ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию =
		ПолнаяИсторияЗадач_ИсторияВыполнения.ПоказыватьПолнуюИсториюПользователю();
	Элементы.ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию.Пометка =
		ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию;

КонецПроцедуры

#КонецОбласти

#Область ОбработчикиКомандФормы

&НаКлиенте
Процедура ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию(Команда)

	ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию = Не ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию;
	ПолнаяИсторияЗадач_ПрименитьНастройку();

КонецПроцедуры

#КонецОбласти

#Область СлужебныеПроцедурыИФункции

&НаСервере
Процедура ПолнаяИсторияЗадач_ПрименитьНастройку()

	Элементы.ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию.Пометка =
		ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию;

	ПолнаяИсторияЗадач_ИсторияВыполнения.УстановитьПоказыватьПолнуюИсториюПользователю(
		ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию);

	ОбновитьЖизненныйЦикл();

КонецПроцедуры

// Заменяет схему жизненного цикла на полную историю по предмету задачи,
// если включен пункт "Показывать полную историю".
//
&НаСервере
&После("ОбновитьЖизненныйЦикл")
Процедура ПолнаяИсторияЗадач_ОбновитьЖизненныйЦикл()

	Если Не ПолнаяИсторияЗадач_ПоказыватьПолнуюИсторию
		Или Не ЗначениеЗаполнено(ТекущаяЗадача) Тогда
		Возврат;
	КонецЕсли;

	СхемаПолнойИстории = ПолнаяИсторияЗадач_ИсторияВыполнения.СхемаПолнойИстории(ТекущаяЗадача);
	Если СхемаПолнойИстории.Количество() = 0 Тогда
		Возврат;
	КонецЕсли;

	РаботаСЗадачами.ОбновитьЖизненныйЦикл(
		ЭтотОбъект,
		Элементы.ГруппаЖизненныйЦикл,
		Элементы.СтраницаЖизненныйЦиклПрокрутка,
		ДанныеЖизненногоЦикла,
		СхемаПолнойИстории);

	ПолнаяИсторияЗадач_УстановитьВысотыНадписей(СхемаПолнойИстории);

КонецПроцедуры

// Выставляет высоту надписей узлов по количеству строк текста,
// иначе многострочные заголовки и описания обрезаются.
//
// Параметры:
//  Схема - Массив - узлы схемы полной истории.
//
&НаСервере
Процедура ПолнаяИсторияЗадач_УстановитьВысотыНадписей(Схема)

	Для Индекс = 0 По Схема.ВГраница() Цикл

		Если Индекс >= ДанныеЖизненногоЦикла.Количество() Тогда
			Прервать;
		КонецЕсли;

		ЭлементСхемы = Схема[Индекс];
		ЭлементДанных = ДанныеЖизненногоЦикла[Индекс];

		ПолнаяИсторияЗадач_УстановитьВысотуНадписи(ЭлементСхемы.Заголовок, ЭлементДанных.ЗаголовокУзла);
		ПолнаяИсторияЗадач_УстановитьВысотуНадписи(ЭлементСхемы.Описание, ЭлементДанных.ОписаниеДополненияУзла);

	КонецЦикла;

КонецПроцедуры

// Устанавливает высоту одной надписи узла по количеству строк текста.
//
// Параметры:
//  Текст - Строка - текст надписи;
//  ИмяЭлемента - Строка - имя элемента формы.
//
&НаСервере
Процедура ПолнаяИсторияЗадач_УстановитьВысотуНадписи(Текст, ИмяЭлемента)

	Если Не ЗначениеЗаполнено(ИмяЭлемента) Тогда
		Возврат;
	КонецЕсли;

	Строк = 1;
	Если ЗначениеЗаполнено(Текст) Тогда
		Строк = СтрЧислоСтрок(Текст);
	КонецЕсли;
	Если Строк < 1 Тогда
		Строк = 1;
	КонецЕсли;

	Элементы[ИмяЭлемента].Высота = Строк;

КонецПроцедуры

#КонецОбласти

