Функция ЗадачиИсполнителиПроцесса(Процесс)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ РАЗРЕШЕННЫЕ
		|	ЗадачиПроцесса.Ссылка КАК Ссылка
		|ИЗ
		|	Задача.ЗадачаИсполнителя КАК ЗадачиПроцесса
		|ГДЕ
		|	ЗадачиПроцесса.БизнесПроцесс = &Процесс
		|	И ЗадачиПроцесса.ПометкаУдаления = ЛОЖЬ";
	Запрос.УстановитьПараметр("Процесс", Процесс);

	ЗадачиПроцессаМассив = Запрос.Выполнить().Выгрузить().ВыгрузитьКолонку("Ссылка");

	Возврат УпорядочитьПоДате(ЗадачиПроцессаМассив);

КонецФункции

