	Наименование = СокрЛП(Строка(Заголовок));
	Префикс = ПрефиксВетки(Уровень);

	ШиринаЗаголовка = ШиринаСтрокиТекста() - СтрДлина(Префикс);
	Если ШиринаЗаголовка < 12 Тогда
		ШиринаЗаголовка = 12;
	КонецЕсли;

	Узел.Заголовок = ЗаголовокВетки(Наименование, Префикс, ШиринаЗаголовка);
	Узел.Описание = ОписаниеУзла(Исполнитель, ДатаПоступления, Срок, ДатаВыполнения);

	Если ЗначениеЗаполнено(Ссылка) Тогда
		Узел.НавигационнаяСсылка = ПолучитьНавигационнуюСсылку(Ссылка);
	КонецЕсли;

	Возврат Узел;

КонецФункции

// Формирует заголовок узла: ветка вложенности и наименование не длиннее двух строк.
//
// Параметры:
//  Наименование - Строка - полное наименование;
//  Префикс - Строка - префикс ветки вложенности;
//  Ширина - Число - ширина строки наименования в символах.
//
// Возвращаемое значение:
//  Строка - заголовок узла.
//
Функция ЗаголовокВетки(Наименование, Префикс, Ширина)

	МаксимумСтрок = 2;
	Строки = ПереносПоШирине(Наименование, Ширина);

	Если Строки.Количество() > МаксимумСтрок Тогда
		Остаток = Строки[МаксимумСтрок - 1];
		Для Индекс = МаксимумСтрок По Строки.ВГраница() Цикл
			Остаток = Остаток + " " + Строки[Индекс];
		КонецЦикла;
		Строки.Количество(Max(МаксимумСтрок - 1, 0));
		Строки.Добавить(КраткоеНаименование(Остаток, Ширина));
	КонецЕсли;

	Отступ = "";
	Пока СтрДлина(Отступ) < СтрДлина(Префикс) Цикл
		Отступ = Отступ + Символ(160);
	КонецЦикла;

	Результат = "";
	Для Индекс = 0 По Строки.ВГраница() Цикл
		Если Результат <> "" Тогда
			Результат = Результат + Символы.ПС;
		КонецЕсли;
		Результат = Результат + ?(Индекс = 0, Префикс, Отступ) + Строки[Индекс];
	КонецЦикла;

	Возврат Результат;

КонецФункции

