// Формирует строки описания узла: исполнитель, даты и комментарий результата.
//
// Параметры:
//  Исполнитель - Строка - полное представление исполнителя (для задач, у которых
//                исполнитель не вынесен в заголовок);
//  ДатаПоступления - Дата - дата поступления задачи исполнителю;
//  ДатаВыполнения - Дата - дата выполнения;
//  Комментарий - Строка - текст результата выполнения.
//
// Возвращаемое значение:
//  Массив - строки описания узла.
//
Функция СтрокиПодробностей(Исполнитель, ДатаПоступления, ДатаВыполнения, Комментарий)

	Строки = Новый Массив;

	Если ЗначениеЗаполнено(Исполнитель) Тогда
		Строки.Добавить(НСтр("ru = 'Исполнитель: '") + СокрЛП(Строка(Исполнитель)));
	КонецЕсли;
	Если ЗначениеЗаполнено(ДатаПоступления) Тогда
		Строки.Добавить(НСтр("ru = 'Поступила: '") + Формат(ДатаПоступления, "ДФ='dd.MM.yyyy HH:mm'"));
	КонецЕсли;
	Если ЗначениеЗаполнено(ДатаВыполнения) Тогда
		Строки.Добавить(НСтр("ru = 'Выполнена: '") + Формат(ДатаВыполнения, "ДФ='dd.MM.yyyy HH:mm'"));
	КонецЕсли;
	Если ЗначениеЗаполнено(Комментарий) Тогда
		Строки.Добавить(НСтр("ru = 'Комментарий: '") + СокрЛП(Строка(Комментарий)));
	КонецЕсли;

	Возврат Строки;

КонецФункции

// Переносит строки описания по ширине и добавляет отступ уровня.
//
// Параметры:
//  Строки - Массив - строки описания узла;
//  Отступ - Строка - отступ в начало каждой строки описания.
//
// Возвращаемое значение:
//  Строка - описание узла.
//
Функция ОписаниеИзСтрок(Строки, Отступ)

	Ширина = ШиринаСтрокиТекста() - СтрДлина(Отступ);
	Если Ширина < 12 Тогда
		Ширина = 12;
	КонецЕсли;

	Результат = "";
	Для Каждого СтрокаОписания Из Строки Цикл
		Для Каждого Часть Из ПереносПоШирине(СтрокаОписания, Ширина) Цикл
			Если Результат <> "" Тогда
				Результат = Результат + Символы.ПС;
			КонецЕсли;
			Результат = Результат + Отступ + Часть;
		КонецЦикла;
	КонецЦикла;

	Возврат Результат;

КонецФункции

