//
// Возвращаемое значение:
//  Строка - текст результата или пустая строка.
//
Функция КомментарийЗадачи(Задача)

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	Действия.РезультатДействияТекстом КАК Текст
		|ИЗ
		|	Документ.ДействиеЗадачи КАК Действия
		|ГДЕ
		|	Действия.Задача = &Задача
		|	И Действия.РезультатДействияТекстом <> """"
		|УПОРЯДОЧИТЬ ПО
		|	Действия.ДатаВыполнения УБЫВ,
		|	Действия.ДатаНачала УБЫВ";
	Запрос.УстановитьПараметр("Задача", Задача);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() Тогда
		Возврат СокрЛП(Выборка.Текст);
	КонецЕсли;

	Возврат "";

КонецФункции

