// Возвращает характер результата узла: по результату выполнения объекта,
// а если результата нет - по датам.
//
// Параметры:
//  Объект - ЗадачаСсылка.ЗадачаИсполнителя, БизнесПроцессСсылка - объект истории;
//  ДатаВыполнения - Дата - дата выполнения;
//  Отменена - Булево - объект отменен.
//
// Возвращаемое значение:
//  ПеречислениеСсылка.ХарактерыРезультатов - характер результата.
//
Функция ХарактерРезультата(Объект, ДатаВыполнения, Отменена)

	Результат = РезультатВыполненияОбъекта(Объект);
	Если Результат = Перечисления.ВариантыВыполненияПроцессовИЗадач.ПоложительноСЗамечаниями Тогда
		Возврат Перечисления.ХарактерыРезультатов.ПоложительныйСЗамечаниями;
	ИначеЕсли Результат = Перечисления.ВариантыВыполненияПроцессовИЗадач.Положительно Тогда
		Возврат Перечисления.ХарактерыРезультатов.Положительный;
	ИначеЕсли Результат = Перечисления.ВариантыВыполненияПроцессовИЗадач.Отрицательно Тогда
		Возврат Перечисления.ХарактерыРезультатов.Отрицательный;
	КонецЕсли;

	Возврат ХарактерРезультатаПоДате(ДатаВыполнения, Отменена);

КонецФункции

// Возвращает результат выполнения процесса или задачи из регистра результатов.
//
// Параметры:
//  Объект - ЗадачаСсылка.ЗадачаИсполнителя, БизнесПроцессСсылка - объект истории.
//
// Возвращаемое значение:
//  ПеречислениеСсылка.ВариантыВыполненияПроцессовИЗадач - результат или пустая ссылка.
//
Функция РезультатВыполненияОбъекта(Объект)

	Если Не ЗначениеЗаполнено(Объект) Тогда
		Возврат Перечисления.ВариантыВыполненияПроцессовИЗадач.ПустаяСсылка();
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	Результаты.Результат КАК Результат
		|ИЗ
		|	РегистрСведений.РезультатыВыполненияПроцессовИЗадач КАК Результаты
		|ГДЕ
		|	Результаты.Объект = &Объект";
	Запрос.УстановитьПараметр("Объект", Объект);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() Тогда
		Возврат Выборка.Результат;
	КонецЕсли;

	Возврат Перечисления.ВариантыВыполненияПроцессовИЗадач.ПустаяСсылка();

КонецФункции

